  "implementation": "def solve(case):
    if not isinstance(case, dict) or 'threshold' not in case or 'calls' not in case:
        raise ValueError("Invalid case structure")
    threshold = case['threshold']
    calls = case['calls']
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        if not isinstance(call, dict) or 'call_id' not in call or 'loss_without_call' not in call or 'loss_with_call' not in call or 'prediction_tokens' not in call or 'parseable' not in call:
            raise ValueError("Invalid call structure")
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        tokens = call['prediction_tokens']
        parseable = call['parseable']
        gain = loss_without - loss_with
        normalized = gain / tokens
        accepted = parseable and normalized >= threshold
        if accepted:
            accepted_call_ids.append(call_id)
        diagnostics.append({
            'call_id': call_id,
            'accepted': accepted,
            'normalized_gain': round(normalized, 8)
        })
    return {'accepted_call_ids': accepted_call_ids, 'diagnostics': diagnostics}"
}
